const MODULES=[
  {id:"research",intro:"Citation is not punctuation. Before any formatting rule, this unit builds the deeper system: what claims and evidence are, what a citation lets a reader do, and how researchers earn trust. APA 7 is the syntax of that system — this unit is why the syntax exists.",video:{id:"pG7M4xxrmbo",label:"Why we cite sources",by:"Camden-Carroll Library"}, no:"00", title:"Research Foundations", sub:"Why citations exist — claims, evidence, and trust."},
  {id:"foundations",intro:"Every scientific claim stands on evidence — and evidence means nothing if no one can check it. This unit builds the whole mental model: what citations do, how pointers differ from records, and the four slots every APA reference is sorted into.",video:{id:"vBDPLCk9lrc",label:"The 4 elements of every reference",by:"Scribbr"}, no:"01", title:"Foundations", sub:"What citations are and why they exist."},
  {id:"authors",intro:"Someone is always responsible for a source, and APA names that someone with ruthless consistency. This unit turns any name — one researcher, a team of twenty, a ministry — into a sortable, retrievable author element.",video:{id:"qQ0iUeUxazM",label:"Author element deep-dive",by:"Purdue OWL"}, no:"02", title:"Authors", sub:"Who is responsible — and how APA names them."},
  {id:"dates",intro:"A reference without a trustworthy date points at the wrong version of reality. This unit teaches year-only cues, full dates for living web sources, and the honest (n.d.) marker for the rest.",video:{id:"Z1XTYp0qHwI",label:"Dates plus spotting broken references",by:"FAU Libraries"}, no:"03", title:"Dates", sub:"When the source appeared, and when it didn't say."},
  {id:"titles",intro:"Titles carry the identity of the work, so their capitalization carries meaning. This unit teaches sentence case, the proper nouns that survive it, and how to tell a work apart from its container.",video:{id:"7FXMuW0qY9k",label:"Title formatting and sentence case",by:"Purdue OWL"}, no:"04", title:"Titles", sub:"Sentence case, proper nouns, and containers."},
  {id:"journals",intro:"The journal article is the currency of STEM. This unit dissects it completely — venue, volume, issue, pages, identifier — then trains you to spot the eight classic faults editors reject.",video:{id:"teErxDIPP5M",label:"Journal articles masterclass",by:"APA Style by Sam"}, no:"05", title:"Journal Articles", sub:"The core STEM source, end to end."},
  {id:"books",intro:"Books are containers, chapters are works inside containers, and editions version the work. This unit teaches which is which, where editions ride, and how editors get credited.",video:{id:"teErxDIPP5M",label:"Books, edited books and chapters",by:"APA Style by Sam"}, no:"06", title:"Books & Chapters", sub:"Whole books, editions, edited volumes."},
  {id:"web",intro:"Web sources move, update, and hide their authors. This unit teaches full-date pinning, telling authors apart from site names, and writing URLs that stay clickable.",video:{id:"7FXMuW0qY9k",label:"Websites, DOIs and URLs",by:"Purdue OWL"}, no:"07", title:"Web Sources", sub:"Pages, sites, organizations, and URLs."},
  {id:"special",intro:"Reports, datasets, theses, talks, and videos don't fit journal molds — each discloses its nature instead. This unit teaches reading the container and crediting the most specific unit responsible.",video:{id:"teErxDIPP5M",label:"Reports, theses and special cases",by:"APA Style by Sam"}, no:"08", title:"Special Sources", sub:"Reports, datasets, theses, media."},
  {id:"intext",intro:"A reference list nobody can connect to your writing is dead weight. This unit teaches pointers that close claims: parenthetical and narrative voices, teams, organizations, quotations, and multi-source combinations.",video:{id:"opp259YvaoE",label:"In-text citation basics",by:"Scribbr"}, no:"09", title:"In-Text Citation", sub:"Pointers inside real writing."},
  {id:"reflist",intro:"The reference list is a retrieval instrument, not a trophy shelf. This unit teaches alphabetical order, duplicate and mismatch audits, and the hanging-indent finish that makes surnames scannable.",video:{id:"7FXMuW0qY9k",label:"Organizing and alphabetizing lists",by:"Purdue OWL"}, no:"10", title:"Reference Lists", sub:"Order, matching, and inspection."},
  {id:"apply",intro:"Rules memorized in isolation evaporate. This unit puts judgment to work — what needs citing, how to paraphrase honestly, and how to carry a source record into a real STEM mission.",video:{id:"8914hv18xnU",label:"Quotations and plagiarism",by:"APA Style by Sam"}, no:"11", title:"Research Application", sub:"Judgment, paraphrase, and missions."},
];

/* ---------------- 01 FOUNDATIONS ---------------- */
const LESSONS_A=[
/* ---------------- 00 RESEARCH FOUNDATIONS ----------------
   Why citations exist: claims, evidence, traceability, trust.
   Stages use the standard investigation machinery (notice / predict /
   judge / concept / explain / reflect); skills reuse the existing model. */
{id:"q01",mod:"research",title:"Why do researchers cite?",rule:"intext",skills:["intext1","classify"],
 obj:"State what a citation gives a reader that a bare claim cannot.",
 context:"Two students submit the same scientific claim. Student A writes: “Compostable film reduced packaging waste in the 2004 packaging trial (Bohlmann, 2004).” Student B writes: “Compostable film cut packaging waste 40%. Trust me.” A mentor can investigate one of these. Decide which — and why.",
 evidence:[["Student A","Compostable film reduced packaging waste in the 2004 packaging trial (Bohlmann, 2004)."],["Student B","Compostable film cut packaging waste 40%. Trust me."],["The difference","A carries a pointer a stranger can follow. B carries only confidence — and a number nobody can check."]],
 notice:{q:"Which sentence can another researcher actually check?",opts:["Student B — shorter claims are easier to verify","Student A — the pointer names a source and a year to look up","Neither — citations are decoration"],a:1,why:"Verifiability is the test. A pointer into a reference list passes it; confidence does not."},
 predict:{q:"Strip away all formatting rules. What must a citation still hand the reader?",opts:["A path back to the evidence behind the claim","A longer bibliography","The author's biography"],a:0,why:"Formatting changes; the job does not. A citation is a path from claim to evidence."},
 concept:[
  {q:"Student A borrowed a finding. What does (Bohlmann, 2004) give Bohlmann?",opts:["Credit — it names whose work the claim rests on","Nothing — credit is automatic","A higher grade"],a:0,why:"Attribution: the pointer says whose research contributed. That is how science keeps score honestly."},
  {q:"A skeptic reads Student A's sentence. What can they do next?",opts:["Find the reference list, locate Bohlmann (2004), and inspect the trial","Nothing — the citation ends the discussion","Assume the claim is true because it is cited"],a:0,why:"Traceability: the citation hands a skeptic a route to the evidence instead of asking for trust."},
  {q:"Student A joins a conversation of packaging researchers. What does the citation add?",opts:["It connects this claim to previous research others can follow","It proves no further research is needed","It replaces reading Bohlmann's paper"],a:0,why:"Connection: references link new work to earlier work, so readers can follow the thread."}],
 examples:[
  {tag:"A — the pointer",fields:{sourceType:"journal",authors:"Gregory M. Bohlmann",year:"2004",title:"Biodegradable packaging life-cycle assessment",journal:"Environmental Progress",volume:"23",issue:"4",pages:"342–346",doi:"https://doi.org/10.1002/ep.10053"},note:"In text this becomes (Bohlmann, 2004)."},
  {tag:"B — the record",fields:{sourceType:"journal",authors:"Gregory M. Bohlmann",year:"2004",title:"Biodegradable packaging life-cycle assessment",journal:"Environmental Progress",volume:"23",issue:"4",pages:"342–346",doi:"https://doi.org/10.1002/ep.10053"},note:"Same source, full record form at the end."}],
 explain:{q:"A teammate says citations exist only to avoid plagiarism. The fuller answer?",opts:["They let readers verify claims, credit researchers, and follow the research thread","They exist to make papers longer","They are only about punishment"],a:0,rule:"intext"},
 reflect:"In one sentence: what can a reader do with your citation that they cannot do with your sentence alone?"},
{id:"q02",mod:"research",title:"Trace the claim",rule:"order",skills:["intext1","classify"],
 obj:"Walk a claim from sentence to evidence through five stations without getting lost.",
 context:"A report claims: “Biodegradable packaging can reduce persistent plastic waste.” Beneath it sits one pointer: (Bohlmann, 2004). Somewhere behind that pointer stands a real trial with real measurements. Travel the whole chain and say what each station reveals.",
 evidence:[["Station 1 — CLAIM","Biodegradable packaging can reduce persistent plastic waste."],["Station 2 — IN-TEXT CITATION","(Bohlmann, 2004) — a short pointer inside the sentence."],["Station 3 — REFERENCE","Bohlmann, G. M. (2004). Biodegradable packaging life-cycle assessment. Environmental Progress, 37(4), 342–346."],["Station 4 — SOURCE","The published paper: methods, measurements, and analysis."],["Station 5 — ORIGINAL EVIDENCE","The trial data itself: waste weighed, conditions logged, reduction measured."]],
 notice:{q:"Which station tells you HOW the reduction was measured?",opts:["Station 5 — the original evidence, reached through the chain","Station 2 — the pointer alone says enough","Station 1 — the claim describes its own methods"],a:0,why:"The pointer is not the evidence; it is the route. Methods live at the source, not in the sentence."},
 predict:{q:"The reference-list entry for Bohlmann (2004) goes missing. What breaks?",opts:["The chain snaps — the pointer leads nowhere","Nothing — the pointer works alone","The claim becomes stronger"],a:0,why:"Pointer and record are two ends of one link. A pointer without its record strands the reader."},
 concept:[
  {q:"At the CLAIM station, what do you actually have?",opts:["Words asserting something — still unchecked","Verified knowledge","The evidence itself"],a:0,why:"A claim is an assertion. Everything after this station is how a reader checks it."},
  {q:"At the IN-TEXT CITATION station, what did you gain?",opts:["A compact signal naming whose work and which year — without breaking the sentence","The full source record","Proof the claim is true"],a:0,why:"Short in text, complete at the end. The pointer's job is direction, not detail."},
  {q:"At the REFERENCE station, what can you now do?",opts:["Locate the exact publication: journal, volume, pages, identifier","Read the trial data directly","Skip to the conclusion"],a:0,why:"The reference is the retrieval record — everything needed to find the source."},
  {q:"At the SOURCE station, what becomes visible?",opts:["Methods, measurements, analysis — the reasoning you can scrutinize","Only the title page","A certificate of truth"],a:0,why:"Sources show their work. Reading them is how you judge, not just collect."},
  {q:"At the ORIGINAL EVIDENCE station, what have you reached?",opts:["The measurements the claim stands on — the end of the pointer's road","Another pointer to follow","The author's opinion"],a:0,why:"Trace complete: claim → pointer → record → source → evidence. That road is what citation builds."}],
 examples:[
  {tag:"A — the record on the chain",fields:{sourceType:"journal",authors:"Gregory M. Bohlmann",year:"2004",title:"Biodegradable packaging life-cycle assessment",journal:"Environmental Progress",volume:"23",issue:"4",pages:"342–346",doi:"https://doi.org/10.1002/ep.10053"},note:"Station 3 of the chain, written in full."}],
 explain:{q:"Why do researchers say a citation is a pointer rather than evidence?",opts:["It shows where to look instead of containing what was found","Pointers sound more technical","Evidence cannot be written down"],a:0,rule:"order"},
 reflect:"Describe the five stations in your own words. Where would a reader catch you if your claim outran your evidence?"},
{id:"q03",mod:"research",title:"What a citation does",rule:"intext",skills:["intext1","classify"],
 obj:"Name the six jobs a citation performs for a reader.",
 context:"One small pointer — (Hassan & Farouk, 2024) — does six jobs at once inside a sentence about catalysts. Investigate each job separately, then see the whole machine.",
 evidence:[["The pointer","(Hassan & Farouk, 2024) sits inside a sentence about catalysts."],["The record","Hassan, O., & Farouk, L. (2024). Reaction equilibrium in closed aqueous systems. Journal of Chemical Education, 101(6), 2210–2218."],["The question","What does this tiny apparatus actually do for a stranger?"]],
 notice:{q:"A citation does many jobs. Which one is about giving credit?",opts:["Attribute — naming whose work contributed","Locate — finding the journal","Verify — checking the data"],a:0,why:"Each job has a name. Credit belongs to attribution."},
 predict:{q:"Remove the reference list but keep the pointers. Which job breaks first?",opts:["Locate — readers can no longer retrieve full source records","Attribute — the names vanish too","None break"],a:0,why:"Short pointers need their long records. Locate depends on the list."},
 concept:[
  {q:"TRACE — a reader wonders which study sits behind the catalyst claim. What helps?",opts:["The pointer names the study to look up","The sentence length","The journal's reputation alone"],a:0,why:"Trace: the citation finds the source behind the claim."},
  {q:"VERIFY — the reader wants to inspect the equilibrium measurements. What helps?",opts:["The reference record leads to the paper with its data","The pointer, which contains the data","Nothing — verification is impossible"],a:0,why:"Verify: the citation opens the evidence for inspection."},
  {q:"ATTRIBUTE — whose work made the sentence possible?",opts:["Hassan and Farouk — named in the pointer","The reader","Nobody needs naming"],a:0,why:"Attribute: the citation recognizes whose work contributed."},
  {q:"CONNECT — how does this sentence join the wider catalyst literature?",opts:["Its reference threads it into previous research","It stands alone by design","By citing more papers than needed"],a:0,why:"Connect: references show how current work relates to earlier work."},
  {q:"LOCATE — the reader needs the complete source information. Where?",opts:["The reference list entry: journal, volume, pages, identifier","Inside the parentheses","In the author's biography"],a:0,why:"Locate: the reference delivers the full source information."},
  {q:"DISTINGUISH — which words are the student's own contribution?",opts:["Everything outside the cited claim — the pointer marks where borrowing ends","Nothing is theirs once they cite","The citation marks their own ideas"],a:0,why:"Distinguish: the citation separates your contribution from what you borrowed."}],
 examples:[
  {tag:"A — the pointer",fields:{sourceType:"journal",authors:"Matthew M. Hooper; Brenton DeBoef",year:"2009",title:"A green multicomponent reaction for the organic chemistry laboratory: The aqueous Passerini reaction",journal:"Journal of Chemical Education",volume:"86",issue:"9",pages:"1077",doi:"https://doi.org/10.1021/ed086p1077"},note:"Pointer: (Hassan & Farouk, 2024)."},
  {tag:"B — the record",fields:{sourceType:"journal",authors:"Matthew M. Hooper; Brenton DeBoef",year:"2009",title:"A green multicomponent reaction for the organic chemistry laboratory: The aqueous Passerini reaction",journal:"Journal of Chemical Education",volume:"86",issue:"9",pages:"1077",doi:"https://doi.org/10.1021/ed086p1077"},note:"Same source, full record form."}],
 explain:{q:"Why teach six jobs instead of one definition?",opts:["Each job is a different thing a reader can do with your citation","Six sounds more impressive","Definitions are forbidden"],a:0,rule:"intext"},
 reflect:"Pick the two jobs you violated most often in past schoolwork, and say what you will do differently."},
{id:"q04",mod:"research",title:"Claims, evidence, interpretation",rule:"intext",skills:["classify","intext1"],
 obj:"Separate sourced facts from interpretation — and mark each honestly.",
 context:"A lab report reads: “A certain material reduced moisture transfer by 31%. This suggests it may be useful for food packaging.” One sentence reports a measurement; the next reasons about it. A reader must be able to tell which is which — and where the pointer belongs.",
 evidence:[["Measured","A certain material reduced moisture transfer by 31%."],["Reasoned","This suggests it may be useful for food packaging."],["The rule","Pointers sit with borrowed or measured material. Reasoning is labeled as yours."]],
 notice:{q:"Which part is interpretation rather than measurement?",opts:["“This suggests it may be useful” — reasoning about the finding","“Reduced moisture transfer by 31%” — that is the reasoning","Both are measurements"],a:0,why:"Suggests and may be are reasoning words. Measurements report; interpretations reason."},
 predict:{q:"Where must the citation pointer sit?",opts:["With the measured 31% — the borrowed or observed fact","Only at the paragraph's end, anywhere","With your recommendation alone"],a:0,why:"Pointers sit with the material they support, not paragraphs away from it."},
 concept:[
  {q:"A researcher writes: “The trial measured 31%.” That sentence is…",opts:["A claim resting on evidence — it needs a pointer","An interpretation","Common knowledge"],a:0,why:"Measured results are claims about the world. They need pointers."},
  {q:"“This suggests the film could wrap fresh food.” That sentence is…",opts:["Interpretation — reasoning that should be labeled as the writer's","A measured fact","A quotation"],a:0,why:"Could and suggests mark reasoning. Honest writing labels whose reasoning it is."},
  {q:"Which sentence is faithful to a source reporting a 12% reduction?",opts:["“The study measured a 12% reduction under lab conditions.”","“The study proves the material solves moisture loss.”","“The study found some reduction, more or less.”"],a:0,why:"Faithful means same strength, same conditions. Proves and more-or-less both distort."},
  {q:"In CLAIM → EVIDENCE → REASONING → CONCLUSION, where do citations usually belong?",opts:["With the evidence — the borrowed material the reasoning stands on","Only with the conclusion","Nowhere — arguments need no sources"],a:0,why:"Citations anchor the evidence. Reasoning and conclusions are yours to defend."}],
 judge:[
  {s:"“The 2004 packaging trial measured 40% less packaging waste.”",cite:true,why:"A specific measured result — a pointer must carry it to its source."},
  {s:"“This suggests the film could suit fresh-food packaging.”",cite:false,why:"Reasoning about the result — mark it as your interpretation, not the source's."},
  {s:"“Hassan and Farouk report equilibrium shifts in closed systems.”",cite:true,why:"A borrowed finding — attribute it with a pointer."},
  {s:"“We conclude the school-lab setup is worth scaling up.”",cite:false,why:"Your conclusion from the evidence — own it as yours."},
  {s:"“WHO lists air quality among major health risks.”",cite:true,why:"A sourced claim — the reader needs the route to it."},
  {s:"“The two studies disagree, so I will trust the larger trial.”",cite:false,why:"Your judgment call — state it as reasoning, then cite both studies beside their claims."}],
 judgeLabels:["Borrowed or measured — needs a pointer","Your reasoning — label it as yours"],
 explain:{q:"Why must readers be able to separate your reasoning from your sources?",opts:["So they can check the evidence and weigh your reasoning separately","So papers look structured","So citations multiply"],a:0,rule:"intext"},
 reflect:"Take one sentence from your own recent writing. Is it claim, evidence, or interpretation — and where would its pointer sit?"},
{id:"q05",mod:"research",title:"What deserves a citation?",rule:"intext",skills:["classify","intext1"],
 obj:"Judge, statement by statement, what needs a citation.",
 context:"Not every sentence needs a pointer — but every borrowed or verifiable claim does. Eight statements, two buckets. The test never changes: could a reader need a route to check this?",
 evidence:[["The test","Could a reader need a route to check this claim?"],["Bucket 1","Needs a citation — borrowed, measured, or verifiable."],["Bucket 2","No citation needed — common knowledge or your own contribution."]],
 notice:{q:"“Water boils at 100°C at sea level.” Which bucket?",opts:["No citation — stable common knowledge","Needs a citation — it has a number","Needs a citation — water is technical"],a:0,why:"Common knowledge needs no pointer. Numbers alone do not decide — checkability does."},
 predict:{q:"“The trial measured 31% less moisture transfer.” Which bucket?",opts:["Needs a citation — a specific measured result","No citation — results speak for themselves","No citation — numbers are common knowledge"],a:0,why:"Specific, non-obvious, checkable. That is exactly what pointers carry."},
 judge:[
  {s:"“Compostable film cut waste 40% in the Alexandria trial.”",cite:true,why:"A specific trial result — verifiable only through its source."},
  {s:"“Cairo is the capital of Egypt.”",cite:false,why:"Stable common knowledge — no route needed."},
  {s:"“Hassan and Farouk (2024) report equilibrium shifts in closed aqueous systems.”",cite:true,why:"A borrowed research finding — attribute it."},
  {s:"“As Bohlmann (2004) argues, packaging trials should run a full season.”",cite:true,why:"A paraphrased idea — wording changed, ownership did not."},
  {s:"“The author defines sustainability as ‘meeting present needs without harming future capacity’.”",cite:true,why:"A direct quotation — quote marks plus a pointer, always."},
  {s:"“This suggests school labs could adopt the catalyst next term.”",cite:false,why:"Your interpretation — label it as reasoning, not as sourced fact."},
  {s:"“We conclude the evidence supports a pilot program.”",cite:false,why:"Your conclusion from the evidence — own it plainly."},
  {s:"“A 2023 monitoring report records the canal readings.”",cite:true,why:"A source-derived fact — the reader needs the route to that report."}],
 judgeLabels:["Needs a citation","No citation needed"],
 explain:{q:"A student cites every sentence, including common knowledge. What is wrong?",opts:["Over-citation buries the claims that truly need routes","Nothing — more citations are always better","Common knowledge needs citations too"],a:0,rule:"intext"},
 reflect:"Good research starts from a question: question → evidence → claim → citation. Write one research question of yours, and name what evidence would answer it."},
{id:"q06",mod:"research",title:"A cited claim can still be weak",rule:"intext",skills:["classify","intext1"],
 obj:"Tell whether a source actually supports the claim built on it.",
 context:"Two claims, two citations — only one is honest. Claim A: “The trial measured a 12% reduction (Mostafa, 2023).” Claim B: “The study proves the material completely prevents moisture loss (Mostafa, 2023).” Same source, different strength. Match claim strength to evidence strength.",
 evidence:[["Claim A","“The trial measured a 12% reduction (Mostafa, 2023).” — same strength as the source."],["Claim B","“The study proves the material completely prevents moisture loss (Mostafa, 2023).” — stronger than the source."],["The test","Does the source actually support the strength of this statement?"]],
 notice:{q:"What changed between Claim A and Claim B?",opts:["Measured became proves, and 12% became complete prevention — the claim outgrew its source","Only the citation format","Nothing — both say the same"],a:0,why:"Suggests became proves; a measured 12% became complete prevention. The source did not change — the honesty did."},
 predict:{q:"A source says “results suggest…”. The honest student writes…",opts:["“The study suggests…” — same strength, same caution","“The study proves…” — stronger reads better","“The study failed…” — caution means failure"],a:0,why:"Scientific language carries the source's uncertainty forward. Upgrading suggest to prove invents evidence."},
 judge:[
  {s:"“The paper reports a 12% reduction in lab conditions (Mostafa, 2023).”",cite:true,why:"Same strength, same conditions — the claim fits its source."},
  {s:"“The study proves the material eliminates moisture loss (Mostafa, 2023).”",cite:false,why:"Proves and eliminates outrun a measured 12%. Downgrade to what was shown."},
  {s:"“A review of storage trials discusses several arid-grid studies (Aziz, 2023).”",cite:true,why:"An accurate description of what a review does — no overclaim."},
  {s:"“Aziz (2023) settles the storage debate for all climates.”",cite:false,why:"One study cannot settle all climates. Scope the claim to what was tested."},
  {s:"“The authors note the effect appeared only in small samples.”",cite:true,why:"Reporting a limitation honestly — this is good source use."},
  {s:"“Small-sample results guarantee field performance.”",cite:false,why:"Guarantee erases the limitation. May, might, suggests — keep the caution."}],
 judgeLabels:["Source supports the claim","Too strong for this source"],
 explain:{q:"A citation exists, but the source is weak for this claim. Which matters more — that a pointer exists, or what it points to?",opts:["What it points to — a pointer's value comes from its source","That a pointer exists — any citation beats none","They are equal — citations are interchangeable"],a:0,rule:"intext"},
 reflect:"Find one strong word (proves, completely, guarantees) you have used in schoolwork. Rewrite the sentence to match evidence you actually had."},
{id:"q07",mod:"research",title:"Where did this evidence come from?",rule:"order",skills:["classify","intext1"],
 obj:"Tell primary sources from secondary ones — and cite the origin.",
 context:"A review article discusses twelve storage trials, including Aziz (2023). A student cites the review for the claim “Aziz measured…” Stop. The review did not measure anything — Aziz did. Follow the evidence to its origin.",
 evidence:[["Primary","Original research, data, or first-hand material — the trial, the dataset, the thesis with new measurements."],["Secondary","Analysis or synthesis of earlier material — the review, the textbook chapter, the news summary."],["The rule","Cite the origin of the evidence you use. Use syntheses for background, origins for findings."]],
 notice:{q:"A review summarizes Aziz (2023). You want Aziz's measurements. What do you cite?",opts:["Aziz (2023) itself — the origin of the measurements","Only the review — you read it, so cite it","Neither — reviews absorb their sources"],a:0,why:"Cite the origin of the evidence you use. The review is a map; Aziz is the territory."},
 predict:{q:"When is a secondary source the RIGHT thing to cite?",opts:["For background and the shape of a field — what many studies together show","For a specific measurement","Never — secondary sources are banned"],a:0,why:"Syntheses are legitimate for context. Findings belong to their origins."},
 judge:[
  {s:"“A journal paper reporting a new catalyst experiment.”",cite:true,why:"New measurements, first-hand — primary."},
  {s:"“A review article discussing twelve storage trials.”",cite:false,why:"Synthesis of earlier work — secondary."},
  {s:"“A dataset of equilibrium constants on Zenodo.”",cite:true,why:"Original data — primary."},
  {s:"“A textbook chapter summarizing thermodynamics.”",cite:false,why:"Teaching synthesis — secondary."},
  {s:"“A thesis presenting new prosthetic-socket tests.”",cite:true,why:"New measurements — primary, even inside a thesis."},
  {s:"“A news article describing a wheat-rust study.”",cite:false,why:"A report about research — secondary. Trace to the study."}],
 judgeLabels:["Primary source","Secondary source"],
 concept:[
  {q:"A review misstates one trial's result. You cite the review for that result. What happens?",opts:["You inherit the error — one more reason to check origins","Nothing — reviews cannot err","The error disappears"],a:0,why:"Each hop away from the origin can add distortion. Check findings at their source."},
  {q:"Your chain runs: review → Aziz (2023) → trial data. What is this?",opts:["An evidence chain — and your citation should point at the link you actually use","Plagiarism","A reference list"],a:0,why:"Evidence chains are how research connects. Point at the link you stand on."},
  {q:"Why do reference lists mix primary and secondary sources?",opts:["Different links serve different jobs — origins for findings, syntheses for context","By accident","To look longer"],a:0,why:"The list maps your evidence chain; it is not a ranking."}],
 examples:[
  {tag:"A — the origin",fields:{sourceType:"journal",authors:"Matthew M. Hooper; Brenton DeBoef",year:"2009",title:"A green multicomponent reaction for the organic chemistry laboratory: The aqueous Passerini reaction",journal:"Journal of Chemical Education",volume:"86",issue:"9",pages:"1077",doi:"https://doi.org/10.1021/ed086p1077"},note:"The experiment paper itself — first-hand measurements."},
  {tag:"B — the synthesis",fields:{sourceType:"journal",authors:"Sungho Hwang; Hae-seok Lee; Yoonmook Kang",year:"2023",title:"Energy yield comparison between monofacial photovoltaic modules with monofacial and bifacial cells in a carport",journal:"Energy Reports",volume:"9",pages:"3148–3153",doi:"https://doi.org/10.1016/j.egyr.2023.02.011"},note:"A review-style record discussing many trials — background, not origin."}],
 explain:{q:"A student cites only reviews, never origins. What is lost?",opts:["Contact with the actual measurements — findings at one remove","Nothing — reviews contain everything","Time, which is saved"],a:0,rule:"order"},
 reflect:"Name one source you have used that was secondary. What origin stood behind it — and what would you cite now?"},
{id:"q08",mod:"research",title:"Why peer review matters",rule:"order",skills:["classify","ordering"],
 obj:"Say what peer review can and cannot establish.",
 context:"A paper passes peer review and gets published. A student announces: “It is peer reviewed, so it is true.” A researcher winces. Peer review is quality control — not a truth certificate. Learn the difference before you lean on those two words.",
 evidence:[["RESEARCH → METHODS → ANALYSIS → MANUSCRIPT","The work, written up for scrutiny."],["PEER REVIEW → PUBLICATION","Independent experts probe methods, reasoning, and reporting — then it appears."],["OTHER RESEARCHERS","Publication invites the real test: replication, extension, debate."]],
 notice:{q:"“Peer reviewed, therefore true.” What is wrong?",opts:["Review checks the work; it does not guarantee every conclusion","Nothing — that is exactly what it means","Peer review checks grammar only"],a:0,why:"Quality control is not a truth certificate. Reviewed work can still be wrong."},
 predict:{q:"What does publication invite?",opts:["Replication, extension, and debate by other researchers","The end of all questions","Automatic classroom use"],a:0,why:"Publication starts the conversation; it does not end it."},
 concept:[
  {q:"What CAN peer review establish?",opts:["That methods were scrutinized, reasoning probed, and reporting standards met","That every conclusion is correct","That the topic is important"],a:0,why:"Review tests rigor — methods, analysis, honest reporting."},
  {q:"What CAN'T peer review establish?",opts:["That conclusions are correct forever and nothing was missed","That the authors tried","That the journal exists"],a:0,why:"Reviewers miss things; later evidence can overturn conclusions. That is normal science."},
  {q:"Why do researchers still publish full methods and data?",opts:["So others can follow, check, and redo the work — traceability","To fill pages","Because reviewers enjoy reading"],a:0,why:"Reproducibility is the infrastructure peer review points at: locate, inspect, compare."},
  {q:"A cited paper is later corrected. Does the original citation become dishonest?",opts:["No — but responsible writers check whether corrections affect their claim","Yes — citing it was always wrong","Only if the teacher notices"],a:0,why:"Science updates. Traceability lets readers — and you — follow the update."}],
 explain:{q:"How do citations connect to peer review?",opts:["References let any reader walk from a claim to the scrutinized work behind it","They replace peer review","They are unrelated systems"],a:0,rule:"order"},
 reflect:"Write the honest version of “peer reviewed, so true” in one sentence."},
{id:"q09",mod:"research",title:"Paraphrase lab",rule:"intext",skills:["classify","intext1"],
 obj:"Tell copying, too-close paraphrase, and genuine paraphrase apart — and attribute each.",
 context:"Source sentence (Mostafa, 2023): “Water hyacinth removed up to 68% of dissolved lead from canal water within 14 days.” Four students reuse it. One copies. One swaps words. One truly paraphrases. One quotes. Only some of them are honest. Judge each version.",
 evidence:[["Copy","“Water hyacinth removed up to 68% of dissolved lead from canal water within 14 days.” — no pointer."],["Too close","“Water hyacinth eliminated as much as 68% of dissolved lead from canal water in 14 days (Mostafa, 2023).”"],["Genuine","“In two weeks, canal water exposed to water hyacinth lost over two-thirds of its dissolved lead (Mostafa, 2023).”"],["Quotation","“Water hyacinth removed up to 68% of dissolved lead from canal water within 14 days” (Mostafa, 2023)."]],
 notice:{q:"The “too close” version carries a citation. Why is it still a problem?",opts:["Changing a few words is not paraphrasing — the sentence structure is still borrowed","Citations cannot fix anything","It is actually perfect"],a:0,why:"A pointer attributes the idea, but the writing is still the author's. Paraphrase means rethinking, not rewording."},
 predict:{q:"What makes the genuine version honest?",opts:["New sentence structure carrying the same finding, plus a pointer","It is shorter","It drops the numbers"],a:0,why:"Restructured thinking plus attribution. The numbers stay — precision belongs to the source."},
 judge:[
  {s:"A copy of the source sentence with no pointer.",cite:false,why:"Direct copying without attribution — fix with quotation plus pointer, or genuine paraphrase."},
  {s:"A word-swapped version with a pointer (the “too close” draft).",cite:false,why:"A citation does not launder borrowed structure. Rethink the sentence."},
  {s:"A restructured sentence with the same finding plus (Mostafa, 2023).",cite:true,why:"Genuine paraphrase: new structure, kept precision, attributed."},
  {s:"The exact sentence in quote marks with (Mostafa, 2023).",cite:true,why:"Honest quotation: visible borrowing, visible source."},
  {s:"“I think canals need floating-plant trials before any rollout.” — your recommendation.",cite:true,why:"Your own reasoning needs no pointer — label it as yours."},
  {s:"Three sources stitched into one paragraph with a single pointer at the end.",cite:false,why:"Patchwork hides which idea came from where. Point each borrowed part to its source."}],
 judgeLabels:["OK as written","Needs fixing"],
 examples:[
  {tag:"A — the source record",fields:{sourceType:"journal",authors:"Sasadhar Jana; Monojit A. Choudhuri",year:"1981",title:"Glycolate metabolism of three submersed aquatic angiosperms: Effect of heavy metals",journal:"Aquatic Botany",volume:"11",pages:"67–77",doi:"https://doi.org/10.1016/0304-3770(81)90047-4"},note:"What every version above must point to."}],
 explain:{q:"A paraphrase changes the wording. Why must it still be cited?",opts:["The underlying idea still belongs to the source — wording was never the point","Citations reward long sentences","Only quotations need pointers"],a:0,rule:"intext"},
 reflect:"Rewrite the source sentence above in genuinely your own structure — then add its pointer."},
{id:"q10",mod:"research",title:"Quote or paraphrase?",rule:"intext",skills:["intextN","intext1"],
 obj:"Decide when to quote and when to paraphrase.",
 context:"A student quotes everything: definitions, results, background, opinions — forty quoted lines. The paper reads like a collage. Quotation is a precision tool, not a default. Learn when it earns its keep.",
 evidence:[["Quote when","Exact wording matters: definitions, unusually precise claims, language under analysis."],["Paraphrase when","The idea matters more than the phrasing — most results, background, and reasoning."],["The cost","Every quotation surrenders your voice. Spend it where precision pays."]],
 notice:{q:"Which moment earns a quotation?",opts:["A definition whose exact wording the class will be tested on","A routine background fact","A paragraph you did not feel like rewriting"],a:0,why:"Quote for precision that matters — definitions, exact claims, analyzed language."},
 predict:{q:"A results section reports twelve measurements. Quote or paraphrase?",opts:["Paraphrase — the numbers matter, not the author's phrasing","Quote all twelve sentences","Quote half for balance"],a:0,why:"Paraphrase carries findings in your voice; quote only where wording itself matters."},
 concept:[
  {q:"“Sustainability means meeting present needs without harming future capacity.” Why quote this?",opts:["It is a definition — exact wording carries the meaning","It is long","Definitions cannot be paraphrased"],a:0,why:"Definitions are precision instruments. Quote them, then cite."},
  {q:"A paper's result is unusually precise: “68% within 14 days.” Quote?",opts:["Paraphrase with the numbers kept — precision survives restructuring","Quote — numbers must stay in original sentences","Drop the numbers"],a:0,why:"Numbers are not wording. Keep them exact inside your own sentence."},
  {q:"You are analyzing how a report phrases risk (“may”, “could”). Quote?",opts:["Quote — the language itself is your evidence","Paraphrase — never quote verbs","Summarize without citing"],a:0,why:"When language is the object of study, quote it exactly."},
  {q:"Forty quoted lines in one paper. The problem?",opts:["Collage writing — the student's voice and reasoning vanish","Too much honesty","Quotations are always wrong"],a:0,why:"Over-quotation outsources thinking. Your synthesis is the contribution."}],
 explain:{q:"Both quoting and paraphrasing need pointers. What decides narrative vs parenthetical voice?",opts:["Whether the author's name drives your sentence — Bohlmann (2004) argues… vs …(Bohlmann, 2004)","The number of authors","The journal's impact"],a:0,rule:"intext"},
 reflect:"Find one quotation in your past writing that should have been a paraphrase — or the reverse. Say which and why."},
{id:"q11",mod:"research",title:"Read the limitations",rule:"order",skills:["classify","ordering"],
 obj:"Match sources to questions — and admit what a source cannot support.",
 context:"Question: do low-cost catalysts work in school labs? On the desk: a catalyst experiment paper, a vendor brochure, a 2011 review, a temperature dataset. Not every source serves every question. Choose like a researcher — and say what each source cannot do.",
 evidence:[["The question","Do low-cost catalysts shift equilibrium in school-lab conditions?"],["The desk","An experiment paper · a vendor brochure · a 2011 review · a temperature dataset."],["The discipline","Right source, right job — plus an honest list of what each cannot support."]],
 notice:{q:"For the catalyst question, which source carries the most weight?",opts:["The experiment paper testing catalysts in school-lab conditions","The vendor brochure praising its own catalyst","The 2011 review alone"],a:0,why:"Fit decides: direct, relevant evidence for this exact question outranks louder or older material."},
 predict:{q:"What can the 2011 review still do for you?",opts:["Background and context — the shape of the field then","Prove current school-lab performance","Nothing at all"],a:0,why:"Older syntheses serve background. Current claims need current evidence."},
 judge:[
  {s:"The experiment paper, for “does it work in school labs?”.",cite:true,why:"Direct evidence for the exact question — the right tool."},
  {s:"The vendor brochure, for “is this catalyst effective?”.",cite:false,why:"It exists to persuade and advertise — the wrong tool for an efficacy claim."},
  {s:"The 2011 review, for “what did the field know in 2011?”.",cite:true,why:"A synthesis fits a background question about its own era."},
  {s:"The temperature dataset alone, for “which catalyst should we buy?”.",cite:false,why:"Numbers without context cannot choose a product — the wrong tool."},
  {s:"The dataset plus the experiment paper, for “at which temperatures did it work?”.",cite:true,why:"Combined, they answer precisely what each supports."},
  {s:"Only the supportive study, hiding two that found weaker effects.",cite:false,why:"Cherry-picking: honest research represents relevant evidence, including disagreement."}],
 judgeLabels:["Right source for this question","Wrong tool for this question"],
 concept:[
  {q:"A study's abstract lists small samples and lab-only conditions. What can it support?",opts:["Lab-scale findings — not field guarantees","Any claim you need","Nothing — limited studies are useless"],a:0,why:"Read the limitations: support what was tested, admit the rest."},
  {q:"Who produced this source, and why?",opts:["Always ask — methods, goals, and omissions shape what you can claim","Never ask — all sources are equal","Only ask for websites"],a:0,why:"Sources have purposes. Persuasion, advertising, and reporting are different jobs."},
  {q:"Study A supports your claim; B finds a weaker effect; C disagrees. Cite?",opts:["All three, honestly weighted — readers need the disagreement","Only A — clean stories win","None — disagreement means no claim"],a:0,why:"Responsible research represents relevant evidence honestly — never just the convenient parts."},
  {q:"Journal vs government vs website — which is most trustworthy?",opts:["It depends on the question, evidence, methods, and context — rank the fit, not the format","Journals always win","Websites always lose"],a:0,why:"No universal ranking. Usefulness is decided per question, per evidence."}],
 explain:{q:"How does the reference list help a reader judge your source choices?",opts:["Full records let readers inspect each source's type, date, and origin","Lists impress reviewers by length","It hides weak sources"],a:0,rule:"order"},
 reflect:"Pick one source you have used. What could it support — and what could it NOT support?"},
{id:"q12",mod:"research",title:"Use sources honestly",rule:"intext",skills:["classify","intext1"],
 obj:"Use sources the way a trustworthy researcher would.",
 context:"Final inspection. Six habits separate honest source use from misuse: inspect what you cite, say what sources say, never invent, stay relevant, show disagreement, and admit uncertainty. Audit each one.",
 evidence:[["The standard","Cite what you inspected. Say what it says. Show the disagreements. Admit the limits."],["The warning","A perfect reference list can still hide weak, unseen, or invented sources."],["The payoff","Citations that survive inspection — and a researcher readers can trust."]],
 notice:{q:"A paper lists 30 citations, another lists 12 highly relevant ones. Which is automatically better?",opts:["Neither — count alone proves nothing about quality","The 30 — more is always better","The 12 — fewer is always better"],a:0,why:"Citation count is not research quality. Relevance and fit decide."},
 predict:{q:"A citation gives the reader a path to a source. Does that path guarantee credibility?",opts:["No — credibility needs source quality, methods, and fit, not just a pointer","Yes — cited means credible","Only for journal sources"],a:0,why:"Citation is traceability. Credibility is earned by what the trace reveals."},
 judge:[
  {s:"Citing a paper you read and inspected.",cite:true,why:"The foundation: never cite blind."},
  {s:"Listing a reference you never opened to look scholarly.",cite:false,why:"Unseen sources can contradict you. Inspect everything you cite."},
  {s:"A reference entry for a paper that does not exist.",cite:false,why:"Invented references are fabrication — the gravest breach."},
  {s:"Quoting a source accurately, with marks and a pointer.",cite:true,why:"Visible borrowing, visible source — honest."},
  {s:"Hiding a study that disagrees with your claim.",cite:false,why:"Concealed disagreement misleads. Represent it and answer it."},
  {s:"Writing “the evidence suggests” where the source only suggests.",cite:true,why:"Matched strength, admitted uncertainty — the STEM standard."}],
 judgeLabels:["Honest source use","Misuse — fix it"],
 concept:[
  {q:"Why is inventing a reference worse than a formatting slip?",opts:["It fabricates the evidence chain itself — formatting errors only garble it","Both are equal","Formatting matters more"],a:0,why:"A wrong comma still points somewhere real. An invented record points nowhere."},
  {q:"Your source says “suggests.” You write “proves.” Who is misrepresented?",opts:["The source's authors — and your reader, who trusts your summary","Nobody — stronger is better","Only yourself"],a:0,why:"Upgraded verbs put words in researchers' mouths. Keep their caution."},
  {q:"What does acknowledging uncertainty cost you?",opts:["Nothing — it marks you as careful, and your strong claims gain weight","Your grade","Your confidence"],a:0,why:"Honest limits strengthen the claims you do make."},
  {q:"The unit's core model, in one line?",opts:["A citation connects a statement to the source behind it; APA is the syntax of that connection","Citations are punctuation","Formatting is the whole job"],a:0,why:"Hold this and the rest of CiteLab has a purpose."}],
 explain:{q:"After this unit, why do we cite sources?",opts:["So readers can trace claims to sources, credit contributors, evaluate evidence, and follow the research thread","Because APA says so","To avoid punishment only"],a:0,rule:"intext"},
 reflect:"What kind of researcher do your citations show you to be — and what will you change first?"},
{id:"f01",mod:"foundations",title:"What citations do",rule:"intext",skills:["intext1"],
 obj:"Explain what a citation is for: letting a reader verify a claim.",
 context:"Your capstone report claims biodegradable packaging cut waste 40% in a trial. Your mentor circles the sentence and writes one word: “Source?” A citation is your answer — a pointer a stranger can follow to check you.",
 evidence:[["Your sentence","Biodegradable packaging cut waste 40% in the Alexandria trial."],["Reader's question","Which trial? Says who?"],["What you owe","A retrievable pointer, not just a name."]],
 notice:{q:"Which of these lets a stranger VERIFY the claim?",opts:["“Many scientists agree.”","“(Bohlmann, 2004) — full reference in the list.”","“I read it somewhere.”"],a:1,why:"Verifiability is the test. A pointer into a reference list passes; vibes do not."},
 predict:{q:"Before any rule: what two things must every citation system provide?",opts:["A pointer in the text + a full record at the end","A link and nothing else","The author's biography"],a:0,why:"Citation = short in-text pointer. Reference = full record. You need both halves."},
 examples:[
  {tag:"A — the pointer",fields:{sourceType:"journal",authors:"Gregory M. Bohlmann",year:"2004",title:"Biodegradable packaging life-cycle assessment",journal:"Environmental Progress",volume:"23",issue:"4",pages:"342–346",doi:"https://doi.org/10.1002/ep.10053"},note:"In text this becomes (Bohlmann, 2004)."},
  {tag:"B — the record",fields:{sourceType:"book",authors:"James C. Beasley; Gary W. Witmer",year:"2017",title:"Ecology and management of terrestrial vertebrate invasive species in the United States",publisher:"CRC Press",doi:"https://doi.org/10.1201/9781315157078"},note:"The full record lives at the end, alphabetical by surname."}],
 explain:{q:"Why do citations exist?",opts:["So readers can verify claims and credit researchers","To make papers look longer","Because teachers enjoy formatting"],a:0,rule:"intext"},
 concept:[
  {q:"A classmate says citations are just anti-plagiarism paperwork. The deeper truth?",opts:["They join a evidence chain other researchers can re-walk","They are only about avoiding punishment","They replace reading the source"],a:0,why:"Credit matters. Verifiability matters more — science runs on checkable claims."},
  {q:"Which claim most needs a citation?",opts:["“The 2004 packaging trial measured 40% less waste.”","“Water is wet.”","“This section discusses packaging.”"],a:0,why:"Specific, verifiable, non-obvious claims need pointers. Common knowledge does not."}],
 reflect:"In one sentence: what does a reader gain from your citation that your sentence alone cannot give?"},
{id:"f02",mod:"foundations",title:"Citation vs reference",rule:"intext",skills:["intext1","ordering"],
 obj:"Distinguish the short in-text pointer from the full reference-list record.",
 context:"Two students argue. One says the citation IS “(Bohlmann, 2004)”. The other says it IS the full paragraph at the end. Both are half right — investigate the halves.",
 evidence:[["In the sentence","(Bohlmann, 2004)"],["At the end","Bohlmann, G. M. (2004). Biodegradable packaging life-cycle assessment. …"],["Relationship","The short form points; the long form delivers."]],
 identify:{intro:"Select every IN-TEXT pointer (not full references).",cite:[{t:"(Bohlmann, 2004)",hit:"intext",why:"Short pointer inside writing.",fix:"(Bohlmann, 2004)"},{t:" showed waste fell.",hit:null},{t:"Bohlmann, G. M. (2004). Biodegradable packaging life-cycle assessment. Environmental Progress, 37(4), 342–346.",hit:null},{t:" As Bohlmann (2004) argues,",hit:"intext",why:"Narrative pointer — author in the sentence flow.",fix:"Bohlmann (2004)"}],errors:["intext"]},
 predict:{q:"The reference list holds full records. What must every in-text pointer match?",opts:["An entry in the reference list, surname + year","The journal's homepage","Nothing — they are independent"],a:0,why:"Pointer and record are two ends of one link. Mismatches strand the reader."},
 examples:[
  {tag:"A — pointer",fields:{sourceType:"journal",authors:"Matthew M. Hooper; Brenton DeBoef",year:"2009",title:"A green multicomponent reaction for the organic chemistry laboratory: The aqueous Passerini reaction",journal:"Journal of Chemical Education",volume:"86",issue:"9",pages:"1077",doi:"https://doi.org/10.1021/ed086p1077"},note:"Pointer: (Hassan & Farouk, 2024)."},
  {tag:"B — record",fields:{sourceType:"journal",authors:"Matthew M. Hooper; Brenton DeBoef",year:"2009",title:"A green multicomponent reaction for the organic chemistry laboratory: The aqueous Passerini reaction",journal:"Journal of Chemical Education",volume:"86",issue:"9",pages:"1077",doi:"https://doi.org/10.1021/ed086p1077"},note:"Same source, full record form."}],
 explain:{q:"A paper cites (Hassan, 2023) in text but the list has no Hassan entry. What broke?",opts:["The pointer–record link — every pointer needs its record","Nothing; lists are decorative","The year is wrong"],a:0,rule:"order"},
 reflect:"Write the rule you would tell a teammate: when do you write a short pointer, and when a full record?"},
{id:"f03",mod:"foundations",title:"In-text vs reference list",rule:"order",skills:["ordering","intext1"],
 obj:"See how one source lives in two places at once.",
 context:"One source, two jobs: a two-word signal inside your paragraph, and a full record at the end. Confuse the jobs and both fail.",
 evidence:[["Paragraph job","Signal the source without breaking reading flow."],["List job","Give everything needed to retrieve the source."],["Shared key","Surname + year, identical in both places."]],
 identify:{intro:"Select the part that belongs ONLY in the reference list.",cite:[{t:"(Aziz, 2023)",hit:null},{t:" showed arid-grid storage works.",hit:null},{t:"Energy Reports, 9, 512–520. https://doi.org/10.1016/j.egyr.2023.02.011",hit:"order",why:"Container, pages and identifier live only in the list.",fix:"(list only)"}],errors:["order"]},
 predict:{q:"Where do volume, pages and DOI appear?",opts:["Only in the reference list","Inside every in-text citation","In the paragraph, spelled out"],a:0,why:"In-text stays short: surname + year. Retrieval detail lives at the end."},
 examples:[
  {tag:"A — signal",fields:{sourceType:"journal",authors:"Sungho Hwang; Hae-seok Lee; Yoonmook Kang",year:"2023",title:"Energy yield comparison between monofacial photovoltaic modules with monofacial and bifacial cells in a carport",journal:"Energy Reports",volume:"9",pages:"3148–3153",doi:"https://doi.org/10.1016/j.egyr.2023.02.011"},note:"Signal: Aziz (2023) or (Aziz, 2023)."},
  {tag:"B — retrieval",fields:{sourceType:"journal",authors:"Sungho Hwang; Hae-seok Lee; Yoonmook Kang",year:"2023",title:"Energy yield comparison between monofacial photovoltaic modules with monofacial and bifacial cells in a carport",journal:"Energy Reports",volume:"9",pages:"3148–3153",doi:"https://doi.org/10.1016/j.egyr.2023.02.011"},note:"Record carries journal, volume, pages, DOI."}],
 explain:{q:"Why must the surname + year match exactly in both places?",opts:["It is the shared key linking signal to record","APA likes repetition","Reviewers count matches"],a:0,rule:"intext"},
 reflect:"Sketch the chain in words: source → ? → ? → reference list."},
{id:"f04",mod:"foundations",title:"Source anatomy + APA order",rule:"order",skills:["ordering","author","date"],
 obj:"Name the parts of a source and assemble them in APA's fixed order.",
 context:"A raw source record lands on your desk: names, numbers, titles, identifiers. APA is a sorting machine with fixed slots. Learn the slots once; every source type reuses them.",
 evidence:[["Researcher","Jane Smith","author"],["Published","2025","date"],["Article","Effects of microplastics on freshwater ecosystems","title"],["Journal","Environmental Research","journal"],["Volume","14","volume"],["Issue","3","volume"],["Pages","44–58","pages"],["DOI","doi:10.1016/j.envres.2026.124161","doi"]],
 predict:{q:"Eight facts, four slots. Which fact opens an APA reference?",opts:["Researcher — Jane Smith","Published — 2025","Article title","Journal name"],a:0,why:"Author → Date → Title → Source. Responsibility first, always."},
 examples:[
  {tag:"A — full anatomy",fields:{sourceType:"journal",authors:"Md. Saiful Islam; Gangadhar Andaluri",year:"2026",title:"Mechanistic insights into PFAS adsorption on microplastics: Effects of contaminant properties and water chemistry",journal:"Environmental Research",volume:"297",pages:"124161",doi:"https://doi.org/10.1016/j.envres.2026.124161"},note:"All eight facts seated in four slots."},
  {tag:"B — thin record",fields:{sourceType:"journal",authors:"Tarek Samy",year:"2024",title:"Microgrid control for desert schools",journal:"Energy Reports",volume:"11",pages:"88–99"},note:"No issue, no DOI — the slots still hold."}],
 build:{notes:["Md. Saiful Islam|AUTHOR","Gangadhar Andaluri|AUTHOR","2026|DATE","Mechanistic insights into PFAS adsorption on microplastics: Effects of contaminant properties and water chemistry|TITLE","Environmental Research|JOURNAL","297|VOLUME","124161|PAGES","doi:10.1016/j.envres.2026.124161|DOI"],order:["author","date","title","journal","volume","pages","doi"]},
 explain:{q:"Why does APA fix the order instead of letting authors choose?",opts:["Predictability: any reader knows where each fact lives","Tradition with no function","To make citations longer"],a:0,rule:"order"},
 blind:{evidence:[["Mona Aziz","?"],["2023","?"],["Renewable energy storage in arid grids","?"],["Energy Reports","?"],["9","?"],["512–520","?"]],answer:["author","date","title","journal","volume","pages"],exp:{sourceType:"journal",authors:"Sungho Hwang; Hae-seok Lee; Yoonmook Kang",year:"2023",title:"Energy yield comparison between monofacial photovoltaic modules with monofacial and bifacial cells in a carport",journal:"Energy Reports",volume:"9",pages:"3148–3153",doi:"https://doi.org/10.1016/j.egyr.2023.02.011"}},
 transfer:{brief:"Same slots — a physics source you have never seen:",evidence:[["Tarek Samy","?"],["2024","?"],["Microgrid control for desert schools","?"],["Energy Reports","?"],["11","?"],["31-44","?"]],answer:["author","date","title","journal","volume","pages"],exp:{sourceType:"journal",authors:"Tarek Samy",year:"2024",title:"Microgrid control for desert schools",journal:"Energy Reports",volume:"11",pages:"31-44"},focus:{q:"The evidence shows `31-44`. Your reference must show…?",opts:["31–44. (en dash + period)","31-44 (as found)","pp. 31–44"],a:0,why:"Same rule, new world: en dash, no pp., closing period."}},
 reflect:"Which slot do students most often skip, and what breaks when it is gone?"},

/* ---------------- 02 AUTHORS ---------------- */
{id:"a01",mod:"authors",title:"One author",rule:"author",skills:["author"],
 obj:"Invert one personal name into surname + initials.",
 context:"A paper by Jane Smith must sort under S, not J. APA inverts the name and compresses given names to initials — two mechanical moves.",
 evidence:[["On the paper","Jane Smith","author"],["Goal","Sort under S; save space."]],
 predict:{q:"How should “Jane Smith” open the reference?",opts:["Smith, J.","Jane Smith","J. Smith"],a:0,why:"Surname first for sorting; initial stands in for the given name."},
 examples:[
  {tag:"A — straightforward",fields:{sourceType:"journal",authors:"Albert K. Sawyer",year:"1983",title:"Solubility and Ksp of calcium sulfate: A general chemistry laboratory experiment",journal:"Journal of Chemical Education",volume:"60",issue:"5",pages:"416",doi:"https://doi.org/10.1021/ed060p416"},note:"Smith, J. — one comma, one period after initial."},
  {tag:"B — two given names",fields:{sourceType:"journal",authors:"George M. Ayoub; Lilian Malaeb",year:"2014",title:"Economic feasibility of a solar still desalination system with enhanced productivity",journal:"Desalination",volume:"335",issue:"1",pages:"27–32",doi:"https://doi.org/10.1016/j.desal.2013.12.010"},note:"Watch the surname: El Sayed, O."},
  {tag:"C — trap: initial first",fields:{sourceType:"journal",authors:"Smith J",year:"2024",title:"Effects of microplastics",journal:"Environmental Science",volume:"14",issue:"2",pages:"31–44"},note:"Even messy “Smith J” resolves to Smith, J."}],
 build:{notes:["Gregory M. Bohlmann|AUTHOR","2004|DATE","Biodegradable packaging life-cycle assessment|TITLE","Environmental Progress|JOURNAL","23|VOLUME","4|ISSUE","342–346|PAGES"],order:["author","date","title","journal","volume","pages"]},
 explain:{q:"Why initials instead of full first names?",opts:["Compact, sortable records — the initial identifies without clutter","APA dislikes first names","To hide identities"],a:0,rule:"author"},
 blind:{evidence:[["Nour El-Din","?"],["2023","?"],["Material strength in low-cost prosthetics","?"],["Journal of Engineering in Medicine","?"]],answer:["author","date","title","journal"],exp:{sourceType:"journal",authors:"Merel van der Stelt; Luc Verhamme; Cornelis H. Slump; Lars Brouwers; Thomas J. J. Maal",year:"2021",title:"Strength testing of low-cost 3D-printed transtibial prosthetic socket",journal:"Proceedings of the Institution of Mechanical Engineers, Part H: Journal of Engineering in Medicine",volume:"236",issue:"3",pages:"367–375"}},
 transfer:{brief:"Same inversion — an unfamiliar hyphenated surname:",evidence:[["Sara El-Masry","?"],["2022","?"],["Drip irrigation scheduling","?"],["Agricultural Water Management","?"]],answer:["author","date","title","journal"],exp:{sourceType:"journal",authors:"Sara El-Masry",year:"2022",title:"Drip irrigation scheduling",journal:"Agricultural Water Management",volume:"270",pages:"15–24"},focus:{q:"“Sara El-Masry” becomes…?",opts:["El-Masry, S.","Masry, S. E.","Sara, E."],a:0,why:"Hyphenated surnames stay whole; only given names compress."}},
 reflect:"What are the two moves APA performs on “Jane Smith”, and why each?"},
{id:"a02",mod:"authors",title:"Two authors",rule:"author",skills:["author","intext2"],
 obj:"Join two authors with a comma and an ampersand; name both in text.",
 context:"Hassan and Farouk co-wrote the equilibrium paper. Dropping either name steals credit — APA keeps both, everywhere.",
 evidence:[["Researcher 1","Omar Hassan","author"],["Researcher 2","Lina Farouk","author"],["Published","2024","date"]],
 predict:{q:"How do two authors join in the reference list?",opts:["Hassan, O., & Farouk, L.","Hassan, O. and Farouk, L.","O. Hassan, L. Farouk"],a:0,why:"Commas separate; & closes before the final author."},
 examples:[
  {tag:"A — reference",fields:{sourceType:"journal",authors:"Matthew M. Hooper; Brenton DeBoef",year:"2009",title:"A green multicomponent reaction for the organic chemistry laboratory: The aqueous Passerini reaction",journal:"Journal of Chemical Education",volume:"86",issue:"9",pages:"1077",doi:"https://doi.org/10.1021/ed086p1077"},note:"Comma between, & before last."},
  {tag:"B — trap: “and”",fields:{sourceType:"journal",authors:"Omar Hassan and Lina Farouk",year:"2024",title:"Reaction equilibrium in closed aqueous systems",journal:"Journal of Chemical Education",volume:"101",pages:"2210–2218"},note:"Raw “and” still resolves — but you must write &."}],
 build:{notes:["Matthew M. Hooper|AUTHOR","Brenton DeBoef|AUTHOR","2009|DATE","A green multicomponent reaction for the organic chemistry laboratory: The aqueous Passerini reaction|TITLE","Journal of Chemical Education|JOURNAL"],order:["author","date","title","journal"]},
 explain:{q:"In text, two authors look like…?",opts:["(Hassan & Farouk, 2024) — & inside parentheses","(Hassan and Farouk, 2024)","(Hassan et al., 2024)"],a:0,rule:"intext"},
 blind:{evidence:[["Tarek Samy; Dina K.", "?"],["2024","?"],["Microgrid control","?"],["Energy Reports","?"]],answer:["author","date","title","journal"],exp:{sourceType:"journal",authors:"Tarek Samy; Dina Kamal",year:"2024",title:"Microgrid control for desert schools",journal:"Energy Reports",volume:"11",pages:"88–99"}},
 transfer:{brief:"Same rule — new pair, new field:",evidence:[["Hana Mostafa; Omar Fathy","?"],["2023","?"],["Canal biofilters","?"],["Aquatic Botany","?"]],answer:["author","date","title","journal"],exp:{sourceType:"journal",authors:"Hana Mostafa; Omar Fathy",year:"2023",title:"Canal biofilters",journal:"Aquatic Botany",volume:"188",pages:"103–112"},focus:{q:"Narrative form for two authors?",opts:["Hassan and Farouk (2024)","Hassan & Farouk (2024)","Hassan et al. (2024)"],a:0,why:"Narrative uses “and”; & lives only inside parentheses."}},
 reflect:"When do you write & and when do you write “and”?"},
{id:"a03",mod:"authors",title:"Three or more authors",rule:"author",skills:["author","intextM"],
 obj:"Keep up to 20 in the list; collapse to et al. in text.",
 context:"Four researchers built the wheat-rust detector. The reference list honors all four; the sentence cannot carry four names every time.",
 evidence:[["Team","Karim Adel; Lina Farouk; Youssef Nader; Mona Aziz","author"],["Published","2025","date"]],
 predict:{q:"Four authors in the reference list become…?",opts:["All four, commas, & before the last","First author + et al.","First two only"],a:0,why:"References keep up to 20. et al. is an in-text shortcut, not a list shortcut."},
 examples:[
  {tag:"A — full list",fields:{sourceType:"journal",authors:"Mohsen Azadbakht; Davoud Ashourloo; Hossein Aghighi; Soheil Radiom; Abbas Alimohammadi",year:"2019",title:"Wheat leaf rust detection at canopy scale under different LAI levels using machine learning techniques",journal:"Computers and Electronics in Agriculture",volume:"156",pages:"119–128",doi:"https://doi.org/10.1016/j.compag.2018.11.016"},note:"Three commas, one &."},
  {tag:"B — trap: et al. in the list",fields:{sourceType:"journal",authors:"Karim Adel; Lina Farouk; Youssef Nader",year:"2025",title:"Deep learning for wheat-rust detection",journal:"Computers and Electronics in Agriculture",volume:"215",pages:"88–99"},note:"Three authors still list fully — et al. would be wrong here."}],
 build:{notes:["Mohsen Azadbakht|AUTHOR","Davoud Ashourloo|AUTHOR","Hossein Aghighi|AUTHOR","Soheil Radiom|AUTHOR","Abbas Alimohammadi|AUTHOR","2019|DATE","Wheat leaf rust detection at canopy scale under different LAI levels using machine learning techniques|TITLE","Computers and Electronics in Agriculture|JOURNAL"],order:["author","date","title","journal"]},
 explain:{q:"In text, this team becomes…?",opts:["(Adel et al., 2025)","(Adel, Farouk, Nader & Aziz, 2025)","(Aziz et al., 2025)"],a:0,rule:"intext"},
 blind:{evidence:[["Adel; Farouk; Nader","?"],["2025","?"],["Wheat-rust detection","?"],["Computers and Electronics in Agriculture","?"]],answer:["author","date","title","journal"],exp:{sourceType:"journal",authors:"Karim Adel; Lina Farouk; Youssef Nader",year:"2025",title:"Wheat-rust detection",journal:"Computers and Electronics in Agriculture",volume:"215",pages:"88–99"}},
 transfer:{brief:"Same rule — medicine this time:",evidence:[["Naguib; Haddad; Saleh; Amin","?"],["2023","?"],["Cold-chain vaccine storage","?"],["Vaccine","?"]],answer:["author","date","title","journal"],exp:{sourceType:"journal",authors:"Sara Naguib; Omar Haddad; Laila Saleh; Karim Amin",year:"2023",title:"Cold-chain vaccine storage",journal:"Vaccine",volume:"41",pages:"300–309"},focus:{q:"Why does the reference keep all four while the sentence keeps one?",opts:["Retrieval needs everyone; reading needs brevity","Journals charge per name in text","Reviewers prefer short lists"],a:0,why:"Two jobs: the list retrieves, the sentence flows."}},
 reflect:"State the 3+ rule in two sentences: one for the list, one for the text."},
{id:"a04",mod:"authors",title:"Organization authors",rule:"org",skills:["author","websites"],
 obj:"Spell group authors out; never invert or abbreviate them in the list.",
 context:"The air-quality fact sheet is by “World Health Organization” — no human name exists. Organizations don't have surnames, so APA treats them verbatim.",
 evidence:[["Author","World Health Organization","author"],["Also seen as","WHO (abbreviation — not for the list)"]],
 predict:{q:"How does WHO appear in the reference list?",opts:["World Health Organization. (spelled out)","WHO.","Skipped — start with the title"],a:0,why:"Lists never abbreviate group authors; abbreviations belong to in-text flow."},
 examples:[
  {tag:"A — spelled out",fields:{sourceType:"website",authors:"World Health Organization",year:"2024",month:"June",day:"11",title:"Air quality and health: global update",siteName:"World Health Organization",url:"https://www.who.int/news-room/fact-sheets/detail/ambient-(outdoor)-air-quality-and-health"},note:"Full name, verbatim, with period."},
  {tag:"B — ministry",fields:{sourceType:"report",authors:"Ministry of Environment",year:"2022",title:"Nile water quality: annual monitoring report",publisher:"Ministry of Environment",url:"https://www.eeaa.gov.eg/nile-water-2022"},note:"Ministries are authors too."},
  {tag:"C — trap: inverted org",fields:{sourceType:"report",authors:"Organization, World Health",year:"2024",title:"Air quality snapshot",publisher:"World Health Organization",url:"https://www.who.int/x"},note:"Never invert an organization — “Organization, W. H.” is fiction."}],
 build:{notes:["World Health Organization|AUTHOR","2024|DATE","Air quality and health|TITLE","World Health Organization|SITE"],order:["author","date","title","journal"]},
 explain:{q:"In text, after first spelling it out, later citations may use…?",opts:["(WHO, 2024) — abbreviation allowed in text after first full use","Still the full name every time","(W. H. O., 2024)"],a:0,rule:"org"},
 place:{para:["Air pollution still drives millions of early deaths each year "," — a burden tracked across member states ","."],ev:{Authors:"World Health Organization",Year:"2024",Work:"Air quality and health"},mode:"paren",correct:{paren:"(World Health Organization, 2024)",narr:"World Health Organization (2024)"},choices:["(World Health Organization, 2024)","(WHO, 2024)","(Organization, 2024)","World Health Organization (2024)"]},
 reflect:"Why does the list forbid abbreviation while the text permits it?"},
{id:"a05",mod:"authors",title:"Missing authors",rule:"author",skills:["author","date"],
 obj:"When no author exists, the title moves first — never invent one.",
 context:"A CRC reference table has no author at all. Deleting the author slot would break the structure — so APA slides the next component forward.",
 evidence:[["Author","(none listed)"],["Article","Equilibrium constants: reference tables"],["Journal","CRC Handbook of Chemistry and Physics"]],
 predict:{q:"No author. What opens the reference?",opts:["The title moves into first position","(Anonymous)","The publisher"],a:0,why:"Missing information changes the structure; it never invents a person."},
 examples:[
  {tag:"A — title first",fields:{sourceType:"journal",authors:"",year:"2022",title:"Equilibrium constants: reference tables",journal:"CRC Handbook of Chemistry and Physics",volume:"104",pages:"5-12–5-20"},note:"Title, then date, then onward — order preserved."},
  {tag:"B — trap: invented author",fields:{sourceType:"journal",authors:"CRC Handbook",year:"2022",title:"Equilibrium constants: reference tables",journal:"CRC Handbook of Chemistry and Physics",volume:"104",pages:"5-12–5-20"},note:"The handbook is the container, not a person — don't promote it."}],
 build:{notes:["Equilibrium constants: reference tables|TITLE","2022|DATE","CRC Handbook of Chemistry and Physics|JOURNAL","104|VOLUME"],order:["author","date","title","journal","volume"]},
 explain:{q:"The engine renders authorless records title-first. Why is that honest?",opts:["It reuses the same order with the next available component","It hides the gap","It looks fuller"],a:0,rule:"order"},
 reflect:"Complete the sentence: missing information changes the ___; it never ___."},
{id:"a06",mod:"authors",title:"Twenty-plus authors",rule:"author",skills:["author","intextM"],
 obj:"Render very long author lists: first 19, ellipsis, final author.",
 context:"A grid-storage paper lists 21 researchers. Your reference cannot carry them all without drowning — APA keeps the first 19, an ellipsis, and the last. Credit scales; records don't explode.",
 evidence:[["Authors","21 named researchers"],["Rule","19 + … + final"],["In text","First surname + et al., as usual."]],
 predict:{q:"21 authors in the list become…?",opts:["First 19, ellipsis, final author","All 21, whatever the length","First author + et al."],a:0,why:"The ellipsis marks honest omission — et al. stays in text only."},
 examples:[
  {tag:"A — trio for contrast",fields:{sourceType:"journal",authors:"Karim Adel; Lina Farouk; Youssef Nader",year:"2025",title:"Deep learning for wheat-rust detection",journal:"Computers and Electronics in Agriculture",volume:"215",pages:"88–99"},note:"Three authors list fully — no ellipsis yet."},
  {tag:"B — 24 authors",fields:{sourceType:"journal",authors:"Jaeki Jeong; Minjin Kim; Jongdeuk Seo; Haizhou Lu; Paramvir Ahlawat; Aditya Mishra; Yingguo Yang; Michael A. Hope; Felix T. Eickemeyer; Maengsuk Kim; Yung Jin Yoon; In Woo Choi; Barbara Primera Darwich; Seung Ju Choi; Yimhyun Jo; Jun Hee Lee; Bright Walker; Shaik M. Zakeeruddin; Lyndon Emsley; Ursula Rothlisberger; Anders Hagfeldt; Dong Suk Kim; Michael Grätzel; Jin Young Kim",year:"2021",title:"Pseudo-halide anion engineering for α-FAPbI3 perovskite solar cells",journal:"Nature",volume:"592",issue:"7854",pages:"381-385",doi:"https://doi.org/10.1038/s41586-021-03406-5"},note:"Count: 19 names, …, Kim. In text: (Jeong et al., 2021)."}],
 identify:{intro:"Which record handles its long list correctly?",cite:[{t:"Hassan, O., et al. (2024). Grid-scale storage. Energy Reports, 12, 1–9.",hit:"author",why:"et al. never appears in reference lists — list names, then ellipsis.",fix:"19 names + … + final"},{t:"Hassan, O., Aziz, M., … Ali, Z. (2024). Grid-scale storage. Energy Reports, 12, 1–9.",hit:null}],errors:["author"]},
 concept:[
  {q:"What survives the ellipsis?",opts:["First 19 plus the final author","First 10","First and last only"],a:0,why:"Endpoints preserved: leaders first, closer last."},
  {q:"In-text treatment changes with list length?",opts:["No — first surname + et al. regardless","Yes — list three for long teams","Yes — cite all"],a:0,why:"Text pointers don't care how long the list is."}],
 explain:{q:"Why not simply list all 2,000 authors of a physics paper?",opts:["Records must stay retrievable without drowning","Printing costs","Readers count names"],a:0,rule:"author"},
 transfer:{brief:"Same ellipsis — a genomics consortium:",evidence:[["Sara Naguib","?"],["2023","?"],["Cold-chain genomics","?"],["Vaccine","?"]],answer:["author","date","title","journal"],exp:{sourceType:"journal",authors:"Sara Naguib; Omar Haddad; Laila Saleh; Karim Amin",year:"2023",title:"Cold-chain genomics",journal:"Vaccine",volume:"41",pages:"310–318"},focus:{q:"A 25-author version of this paper would list…?",opts:["First 19, …, final author","All 25 names","First author + et al."],a:0,why:"The rule scales: 19, ellipsis, closer."}},
 reflect:"When in YOUR STEM work would you ever cite a 20+ author paper?"},

/* ---------------- 03 DATES ---------------- */
{id:"d01",mod:"dates",title:"Publication year",rule:"date",skills:["date"],
 obj:"Place the year in parentheses directly after the author.",
 context:"The reader matched your author — now they need the year to pick the right paper among Smith's many. Parentheses make the year scannable.",
 evidence:[["Author","Smith, J."],["Year on source","2025"],["Goal","(2025). right after the author."]],
 predict:{q:"Where does (2025) sit?",opts:["Directly after the author","After the title","At the very end"],a:0,why:"Author → year is the matching key for every in-text pointer."},
 examples:[
  {tag:"A — standard",fields:{sourceType:"journal",authors:"Albert K. Sawyer",year:"1983",title:"Solubility and Ksp of calcium sulfate: A general chemistry laboratory experiment",journal:"Journal of Chemical Education",volume:"60",issue:"5",pages:"416"},note:"Smith, J. (2025). — period inside."},
  {tag:"B — trap: bare year",fields:{sourceType:"journal",authors:"Jane Smith",year:"2025",title:"Climate change and crop systems",journal:"Journal of Environmental Science",volume:"14"},note:"Same data — the year still needs its parentheses."}],
 build:{notes:["Jane Smith|AUTHOR","2025|DATE","Climate change|TITLE","Journal of Environmental Science|JOURNAL"],order:["author","date","title","journal"]},
 explain:{q:"Why parentheses instead of a bare year?",opts:["They mark the date as one discrete retrieval cue","Decoration","To confuse readers"],a:0,rule:"date"},
 blind:{evidence:[["Omar Hassan","?"],["2024","?"],["Equilibrium","?"],["J. Chem. Educ.","?"]],answer:["author","date","title","journal"],exp:{sourceType:"journal",authors:"Omar Hassan",year:"2024",title:"Equilibrium in closed systems",journal:"Journal of Chemical Education",volume:"101",pages:"2210–2218"}},
 transfer:{brief:"Same cue — an engineering paper:",evidence:[["Nour El-Din","?"],["2023","?"],["Prosthetic sockets","?"],["J. Eng. Med.","?"]],answer:["author","date","title","journal"],exp:{sourceType:"journal",authors:"Nour El-Din",year:"2023",title:"Prosthetic sockets",journal:"Journal of Engineering in Medicine",volume:"237",issue:"9",pages:"1041–1053"},focus:{q:"The year is 2023 but the paper was read in 2025. Which year?",opts:["2023 — publication year, always","2025 — when you read it","Both"],a:0,why:"Cite the source's birthday, not your reading date."}},
 reflect:"What two pieces form the matching key, and where do they sit?"},
{id:"d02",mod:"dates",title:"Full dates",rule:"date",skills:["date","websites"],
 obj:"Carry month and day for sources that version — web pages, videos, datasets.",
 context:"A WHO page updated June 11, 2024 differs from its 2023 version. Year-only would point at the wrong text.",
 evidence:[["Page","Air quality and health"],["Stamp","June 11, 2024"],["Rule","Year first, then month day — inside the same parentheses."]],
 predict:{q:"How does June 11, 2024 appear?",opts:["(2024, June 11).","(June 11, 2024).","(2024)."],a:0,why:"APA orders biggest→smallest: year, month, day."},
 examples:[
  {tag:"A — web page",fields:{sourceType:"website",authors:"World Health Organization",year:"2024",month:"June",day:"11",title:"Air quality and health: global update",siteName:"World Health Organization",url:"https://www.who.int/news-room/fact-sheets/detail/ambient-(outdoor)-air-quality-and-health"},note:"Full date, one cue."},
  {tag:"B — video",fields:{sourceType:"video",authors:"Code for Agriculture",year:"2024",month:"February",day:"2",title:"Training crop models on small datasets",siteName:"YouTube",url:"https://www.youtube.com/watch?v=example"},note:"Same pattern, different container."},
  {tag:"C — trap: journal with month",fields:{sourceType:"journal",authors:"Jane Smith",year:"2025",title:"Climate change and crop systems",journal:"Journal of Environmental Science",volume:"14",pages:"31–44"},note:"Journals stay year-only even when a month is known."}],
 build:{notes:["World Health Organization|AUTHOR","2024, June 11|DATE","Air quality and health|TITLE","World Health Organization|SITE"],order:["author","date","title","journal"]},
 explain:{q:"Why do volatile sources carry more date than journals?",opts:["The date pins which version you saw","Journals forbid months","Longer looks rigorous"],a:0,rule:"date"},
 reflect:"Name two source types that need full dates, and one that must not use them."},
{id:"d03",mod:"dates",title:"No date",rule:"nodate",skills:["date"],
 obj:"Mark missing dates honestly with (n.d.).",
 context:"An undated lab handout still needs citing. Guessing a year would forge evidence; leaving a gap breaks matching.",
 evidence:[["Date on source","(none)"],["Honest marker","(n.d.)"],["Forbidden","guessing, blank space."]],
 predict:{q:"No date anywhere. You write…?",opts:["(n.d.).","(….).","Nothing — skip it"],a:0,why:"An explicit marker beats a silent hole."},
 examples:[
  {tag:"A — undated page",fields:{sourceType:"website",authors:"Nile Research Team",year:"",title:"Canal sensor readings",siteName:"Nile Portal",url:"https://example.com/sensors"},note:"(n.d.) holds the date slot."},
  {tag:"B — trap: guessed year",fields:{sourceType:"website",authors:"Nile Research Team",year:"2023",title:"Canal sensor readings",siteName:"Nile Portal",url:"https://example.com/sensors"},note:"If 2023 is a guess, this record is dishonest — use (n.d.)."}],
 build:{notes:["Nile Research Team|AUTHOR","No date|DATE","Canal sensor readings|TITLE","Nile Portal|SITE"],order:["author","date","title","journal"]},
 explain:{q:"“n.d.” stands for…?",opts:["no date","no data","new draft"],a:0,rule:"nodate"},
 reflect:"Why is a visible (n.d.) more honest than a blank?"},

/* ---------------- 04 TITLES ---------------- */
{id:"t01",mod:"titles",title:"Sentence case",rule:"title",skills:["title"],
 obj:"Capitalize first words only; lowercase the rest.",
 context:"A student submits “Climate Change And Crop Systems”. Every word shouts. APA whispers — first word up, the rest down.",
 evidence:[["As submitted","Climate Change And Crop Systems"],["APA wants","Climate change and crop systems"]],
 predict:{q:"Which is sentence case?",opts:["Climate change and crop systems","Climate Change And Crop Systems","CLIMATE CHANGE AND CROP SYSTEMS"],a:0,why:"First word capitalized; the rest fall — unless proper nouns."},
 examples:[
  {tag:"A — conversion",fields:{sourceType:"journal",authors:"Jane Smith",year:"2025",title:"Climate Change And Crop Systems",journal:"Journal of Environmental Science",volume:"14",pages:"31–44"},note:"Watch And → and."},
  {tag:"B — already clean",fields:{sourceType:"journal",authors:"Sungho Hwang; Hae-seok Lee; Yoonmook Kang",year:"2023",title:"Energy yield comparison between monofacial photovoltaic modules with monofacial and bifacial cells in a carport",journal:"Energy Reports",volume:"9",pages:"3148–3153"},note:"Nothing to change — restraint."},
  {tag:"C — trap: journal lowercased too",fields:{sourceType:"journal",authors:"Jane Smith",year:"2025",title:"Climate change",journal:"journal of environmental science",volume:"14",pages:"31–44"},note:"Sentence case is for TITLES — journal names keep title case."}],
 build:{notes:["Climate Change And Crop Systems|TITLE","2025|DATE","Jane Smith|AUTHOR","Journal of Environmental Science|JOURNAL"],order:["author","date","title","journal"]},
 explain:{q:"Why does APA quiet titles down?",opts:["Neutral, scannable titles; emphasis is reserved for containers","To save ink","Lowercase looks modern"],a:0,rule:"title"},
 blind:{evidence:[["Solar Still Productivity","?"],["2023","?"],["Omar El-Sayed","?"],["Desalination","?"]],keys:["title","date","author","journal"],answer:["author","date","title","journal"],exp:{sourceType:"journal",authors:"Omar El-Sayed",year:"2023",title:"Solar still productivity",journal:"Desalination",volume:"548",pages:"116–128"}},
 transfer:{brief:"Same rule — materials science:",evidence:[["Low-Cost Composite Testing","?"],["2023","?"],["Salma Rashad","?"],["Cairo University","?"]],keys:["title","date","author","publisher"],answer:["author","date","title","publisher"],exp:{sourceType:"thesis",authors:"Salma Rashad",year:"2023",title:"Low-cost composite testing",publisher:"Cairo University"},focus:{q:"“Low-Cost” after conversion?",opts:["Low-cost — only the first word keeps its capital","Low-Cost","low-cost"],a:0,why:"Hyphens don't rescue capitals mid-title."}},
 reflect:"Write the sentence-case rule as an instruction to a teammate."},
{id:"t02",mod:"titles",title:"Proper nouns survive",rule:"title",skills:["title"],
 obj:"Keep proper nouns capitalized inside sentence case — and flag uncertainty.",
 context:"“Invasive Species of the Nile Delta” — lowercasing everything would drown a river. Proper nouns keep their capitals; the system must ask, not guess.",
 evidence:[["Title as found","Invasive Species of the Nile Delta"],["Proper noun inside","Nile, Delta"],["System limit","Already-lowercased nouns can't be rescued."]],
 predict:{q:"Which words must keep capitals?",opts:["Nile, Delta — proper nouns","Species, Delta — longest words","None — lowercase all"],a:0,why:"Proper nouns survive sentence case; common nouns fall."},
 examples:[
  {tag:"A — river kept",fields:{sourceType:"book",authors:"James C. Beasley; Gary W. Witmer",year:"2017",title:"Ecology and management of terrestrial vertebrate invasive species in the United States",publisher:"CRC Press"},note:"Nile and Delta stand; review confirms."},
  {tag:"B — technology kept",fields:{sourceType:"thesis",authors:"Salma Rashad",year:"2023",title:"Low-cost composite testing with Arduino sensors",publisher:"Cairo University"},note:"Arduino is a proper name — kept."}],
 flagwords:{title:"Invasive Species of the Nile Delta",keep:["Nile","Delta"]},
 explain:{q:"The system flags NILE for review instead of deciding silently. Why?",opts:["Only the source — or you — knows it's a proper noun","Flagging is slower","Computers hate rivers"],a:0,rule:"title"},
 concept:[
  {q:"A title mentions “python” lowercase for the language. You…?",opts:["Capitalize to Python and verify against the source","Leave it — lowercase is safer","Delete the word"],a:0,why:"Meaning decides: the language Python is a proper noun; the snake usually isn't. Check the source."},
  {q:"Species name “Tilapia nilotica” in a title keeps…?",opts:["Its scientific capitalization (genus capital, species lower)","All lowercase","All caps"],a:0,why:"Scientific names carry their own eternal rule — APA doesn't override them."}],
 flagwordsB:{title:"Effects on the Nile River with Arduino-based monitoring",keep:["Nile","River","Arduino"]},
 transfer:{brief:"Same judgment \u2014 an engineering title:",evidence:[["Quantum sensors in the Nile Delta","?"],["2025","?"],["Karim Adel","?"],["Sensors Journal","?"]],keys:["title","date","author","journal"],answer:["author","date","title","journal"],exp:{sourceType:"journal",authors:"Karim Adel",year:"2025",title:"Quantum sensors in the Nile Delta",journal:"Sensors Journal",volume:"8",pages:"40\u201348"},focus:{q:"Which words keep capitals?",opts:["Nile, Delta","Quantum, Sensors, Nile, Delta","None"],a:0,why:"First word plus proper nouns only \u2014 same rule, new river."}},
 reflect:"Name three proper-noun categories hiding in STEM titles."},
{id:"t03",mod:"titles",title:"Article vs container",rule:"journal",skills:["title","journal"],
 obj:"Never confuse the work with its venue — casing and italics differ.",
 context:"“Climate change” is the article; “Journal of Environmental Science” is the venue. Students swap their formatting constantly. Learn to see two different objects.",
 evidence:[["Work","Climate change and crop systems (article)"],["Venue","Journal of Environmental Science (container)"],["Signal","Sentence case + plain vs Title Case + italic."]],
 identify:{intro:"Select the CONTAINER (journal/site/publisher) in each specimen.",cite:[{t:"Climate change and crop systems. ",hit:null},{t:"Journal of Environmental Science,",hit:"journal",why:"The venue — title case + italic.",fix:"Journal (container)"},{t:" 14(2).",hit:null}],errors:["journal"]},
 predict:{q:"Which gets italics?",opts:["The journal / book — the container","The article / chapter title","Both, for emphasis"],a:0,why:"Italics mark the container that holds the work."},
 examples:[
  {tag:"A — journal pair",fields:{sourceType:"journal",authors:"Albert K. Sawyer",year:"1983",title:"Solubility and Ksp of calcium sulfate: A general chemistry laboratory experiment",journal:"Journal of Chemical Education",volume:"60",issue:"5",pages:"416"},note:"Plain title, italic venue."},
  {tag:"B — book pair",fields:{sourceType:"book",authors:"Amira Khalil",year:"2023",title:"Materials science for engineers",publisher:"Springer"},note:"Here the book IS the container — italic."},
  {tag:"C — trap: italic article",fields:{sourceType:"journal",authors:"Jane Smith",year:"2025",title:"Climate change and crop systems",journal:"Journal of Environmental Science",volume:"14",pages:"31–44"},note:"If the article looks italic, the formatting is swapped."}],
 explain:{q:"A chapter title vs its book title — same logic?",opts:["Yes: chapter plain, book italic","No: both italic","No: both plain"],a:0,rule:"journal"},
 reflect:"Explain the container test: how do you tell work from venue?"},
{id:"t04",mod:"titles",title:"Colons and subtitles",rule:"title",skills:["title","books"],
 obj:"Capitalize the first word after a colon.",
 context:"“Materials science for engineers: strength and failure” — the subtitle restarts capitalization exactly once, at Strength.",
 evidence:[["Full title","Materials science for engineers: strength and failure"],["Restart point","Strength (first word of subtitle)"]],
 predict:{q:"Correct form?",opts:["Materials science for engineers: Strength and failure","Materials science for engineers: strength and failure","Materials Science For Engineers: Strength And Failure"],a:0,why:"One restart after the colon; everything else follows sentence case."},
 examples:[
  {tag:"A — subtitle",fields:{sourceType:"book",authors:"Bikash Ranjan Parida; Arvind Chandra Pandey; Mukunda Dev Behera; Navneet Kumar",year:"2022",title:"Handbook of Himalayan ecosystems and sustainability, Volume 2: Spatio-temporal monitoring of water resources and climate",publisher:"CRC Press",doi:"https://doi.org/10.1201/9781003265160"},note:"Capital S, lowercase f."},
  {tag:"B — handbook",fields:{sourceType:"journal",authors:"",year:"2022",title:"Equilibrium constants: reference tables",journal:"CRC Handbook of Chemistry and Physics",volume:"104",pages:"5-12–5-20"},note:"Title-first AND subtitle rule combine here."}],
 build:{notes:["Materials science for engineers: strength and failure|TITLE","2023|DATE","Amira Khalil|AUTHOR","Springer|PUBLISHER"],order:["author","date","title","publisher"]},
 explain:{q:"Why does the subtitle get a fresh capital?",opts:["It functions as a second title opening","Colons are decorative","To honor the publisher"],a:0,rule:"title"},
 reflect:"Punctuate this: “field guide” as subtitle of “Invasive species of the Nile Delta”."},
];

